 window.addEventListener("storage",onStorage);window.addEventListener("v-motion-change",onEngine);window.addEventListener("v-flow",onEngine)
 releaseEvents=()=>{window.removeEventListener("storage",onStorage);window.removeEventListener("v-motion-change",onEngine);window.removeEventListener("v-flow",onEngine);releaseEvents=undefined}
}
export function subscribeSettings(fn:()=>void){loadMotionSettings();listeners.add(fn);acquireEvents();return ()=>{listeners.delete(fn);if(!listeners.size)releaseEvents?.()}}
export const subscribeMotion=subscribeSettings
function persist(key:string,value:unknown){try{storage()?.setItem(key,JSON.stringify(value))}catch{/* Controls remain live when storage is unavailable. */}}
function event(name:string){if(typeof window==="undefined")return;dispatching=true;try{window.dispatchEvent(new CustomEvent(name,{detail:name==="v-flow"?getFlowSettings():getMotionSettings()}))}finally{dispatching=false}}
function saveSettings(){persist(MOTION_KEY,{v:3,mode:settings.mode,cats:Object.fromEntries(PRODUCT_CATEGORIES.map(k=>[k,settings.cats[k]]))});publish();event("v-motion-change")}
export function setMotionMode(mode:MotionSettings["mode"]){loadMotionSettings();settings.mode=mode==="off"?"off":"subtle";saveSettings()}
export function setMotionCategory(category:Category,on:boolean){loadMotionSettings();settings.cats[category]=!!on;saveSettings()}
export function setFlowSettings(patch:Partial<FlowSettings>){loadMotionSettings();flow=normalizeFlow({...flow,...patch});persist(FLOW_KEY,flow);publish();event("v-flow")}
export function resetFlow(){setFlowSettings({...FLOW_DEFAULTS})}
export function saveMorph(){loadMotionSettings();authored=true;persist(MORPH_KEY,profile);publish()}
export function setMorphConfig(patch:Partial<MorphConfig>){loadMotionSettings();profile=mergeProfile({cfg:patch},profile,true);saveMorph()}
export function setMorphTier(tier:TierName,patch:Partial<Tier>){loadMotionSettings();profile=mergeProfile({TIER:{[tier]:patch}},profile,true);saveMorph()}
export function exportMorphJSON(){return JSON.stringify({version:4,...getMorphProfile()},null,1)}
export function importMorphJSON(value:string|Partial<MorphProfile>){
 loadMotionSettings();let parsed:unknown=value
 if(typeof value==="string")try{parsed=JSON.parse(value)}catch{throw new Error("Invalid JSON. Paste an exported morph profile with cfg and TIER.")}
 const next=mergeProfile(parsed,profile,true);profile=next;saveMorph()
}
export function resetMorph(){loadMotionSettings();profile=runtime();authored=false;try{storage()?.removeItem(MORPH_KEY)}catch{}publish()}

"use client"
import { useSyncExternalStore } from 'react'
let query:MediaQueryList|undefined
const listeners=new Set<()=>void>()
const changed=()=>listeners.forEach(listener=>listener())
function media(){return query??=window.matchMedia('(prefers-reduced-motion: reduce)')}
function subscribe(listener:()=>void){
 const q=media();if(!listeners.size)q.addEventListener('change',changed);listeners.add(listener)
 return ()=>{listeners.delete(listener);if(!listeners.size){q.removeEventListener('change',changed);query=undefined}}
}
function snapshot(){return typeof window==='undefined'?false:media().matches}
const serverSnapshot=()=>false
/** Dynamic accessibility preference shared by genuine in-progress indicators and other component roles. */
export function useReducedMotion(){return useSyncExternalStore(subscribe,snapshot,serverSnapshot)}

@layer cojeev-states {
[data-slot="agent-state"] {
  --agent-base: var(--v-pink);
  --agent-light: var(--v-yellow);
  --agent-deep: var(--v-pink-deep);
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 12px;
  color: var(--v-text);
}
[data-slot="agent-state"][data-status="thinking"] { --agent-base: var(--v-blue); --agent-light: var(--v-pink); --agent-deep: var(--v-blue-deep); }
[data-slot="agent-state"][data-status="working"] { --agent-base: var(--v-pink); --agent-light: var(--v-yellow); --agent-deep: var(--v-pink-deep); }
[data-slot="agent-state"][data-status="needs-input"] { --agent-base: var(--v-yellow); --agent-light: var(--cream-fixed); --agent-deep: var(--v-yellow-deep); }
[data-slot="agent-state"][data-status="complete"] { --agent-base: var(--v-olive); --agent-light: var(--v-yellow); --agent-deep: var(--v-olive-deep); }
[data-slot="agent-state"][data-status="error"] { --agent-base: var(--v-pink); --agent-light: var(--v-yellow); --agent-deep: var(--v-danger); }
.v-agent-state__field { display: block; width: 88px; height: auto; flex: 0 0 auto; overflow: visible; pointer-events: none; }
.v-agent-state__copy { display: grid; min-width: 0; gap: 4px; }
.v-agent-state__label { font: 600 17px/1.25 var(--font-display); letter-spacing: -.02em; overflow-wrap: anywhere; }
.v-agent-state__description { font: 400 13px/1.45 var(--font-text); color: var(--v-text-2); max-width: 35ch; overflow-wrap: anywhere; }
[data-slot="agent-state"][data-size="sm"] { gap: 4px; }
[data-slot="agent-state"][data-size="sm"] .v-agent-state__field { width: 48px; }
[data-slot="agent-state"][data-size="sm"] .v-agent-state__label { font-family: var(--font-text); font-size: 13px; letter-spacing: 0; }
[data-slot="agent-state"][data-size="sm"] .v-agent-state__description { font-size: 12px; }
[data-slot="agent-state"][data-size="lg"] { flex-direction: column; text-align: center; gap: 0; }
[data-slot="agent-state"][data-size="lg"] .v-agent-state__field { width: min(100%, 216px); }
[data-slot="agent-state"][data-size="lg"] .v-agent-state__label { font-size: 26px; }
[data-slot="agent-state"][data-size="lg"] .v-agent-state__description { max-width: 32ch; margin-inline: auto; font-size: 14px; }
@media (forced-colors: active) {
  .v-agent-state__field { forced-color-adjust: none; }
}

}
